//#region worker/core/concurrency.js
async function runWithConcurrency(items, limit, worker) {
  const queue = Array.isArray(items) ? items : [];
  if (queue.length === 0) return [];
  if (typeof worker !== "function") throw new TypeError("worker must be a function");
  const parsedLimit = Number(limit);
  const concurrency =
    Number.isFinite(parsedLimit) && parsedLimit > 0
      ? Math.min(queue.length, Math.max(1, Math.floor(parsedLimit)))
      : 1;
  const results = Array.from({ length: queue.length });
  let nextIndex = 0;
  const runners = Array.from({ length: concurrency }, async () => {
    while (nextIndex < queue.length) {
      const currentIndex = nextIndex;
      nextIndex += 1;
      const task = Promise.resolve().then(() => worker(queue[currentIndex]));
      results[currentIndex] = task;
      await task.catch(() => {});
    }
  });
  await Promise.all(runners);
  return Promise.all(results);
}
