      const normalizedMutations = (Array.isArray(mutationPlan) ? mutationPlan : [])
        .map((mutation) => ({
          type:
            String(mutation?.type || "put")
              .trim()
              .toLowerCase() === "delete"
              ? "delete"
              : "put",
          key: String(mutation?.key || "").trim(),
        }))
        .filter((mutation) => mutation.key);
