//#region worker/features/maintenance/config-persistence-methods.js
function defineConfigPersistenceMethods(dependencies = {}, kernel = {}) {
  return {
    async persistRuntimeConfig(rawConfig, options = {}) {
      return await runKvDataMutation(options.kv || getKvBinding(options.env))(() =>
        kernel.commitRuntimeConfig(rawConfig, {
          ...options,
          forceKvCommit: true,
        }),
      );
    },
    async prepareRuntimeConfigPersistence(rawConfig, options = {}) {
      const { env, kv, ctx } = options;
      if (!kv) {
        const error = /* @__PURE__ */ new Error(
          "KV namespace is required to persist runtime config",
        );
        error.code = "KV_NOT_CONFIGURED";
        error.status = 503;
        throw error;
      }
      assertHostPrefixCnameTargetValid(rawConfig?.defaultHostPrefixCnameTarget);
      // 这次读取是乐观锁（expectedConfigRevision）的新鲜基线，不能复用调用方早先读到的配置：
      // 并发保存时两者可能读到同一份旧值，导致两个请求都通过校验。
      const prevConfig = env
        ? await getRuntimeConfigStrict(env)
        : sanitizeRuntimeConfig((await kvGetStrict(kv, kernel.CONFIG_KEY, { type: "json" })) || {});
      const nextConfig = sanitizeRuntimeConfig(rawConfig);
      assertAdminIndexSourceConfigValid(rawConfig);
      assertHostPrefixProxyConfigReady(nextConfig, env);
      const configuredHost = resolveConfiguredHost(env);
      const inheritedHostPrefixNodes =
        resolveHostPrefixCnameTarget(null, prevConfig, configuredHost) !==
        resolveHostPrefixCnameTarget(null, nextConfig, configuredHost)
          ? (await kernel.loadAllNodeEntitiesFromKvStrict(kv, { ctx })).filter(
              (node) =>
                isHostPrefixEntryMode(node?.entryMode) &&
                !normalizeHostPrefixCnameTarget(node?.hostPrefixCnameTarget),
            )
          : [];
      if (inheritedHostPrefixNodes.length > 0) assertHostPrefixDnsSyncReady(nextConfig, env);
      return {
        prevConfig,
        nextConfig,
        configuredHost,
        dnsPlans: inheritedHostPrefixNodes
          .map((node) =>
            kernel.buildHostPrefixDnsSyncPlan(node.name, node, node.name, node, configuredHost, {
              previousConfig: prevConfig,
              nextConfig,
            }),
          )
          .filter((plan) => plan.changed === true),
        ctx,
        kv,
        env,
      };
    },
    async buildRuntimeConfigMutationPlan(kv, prevConfig, nextConfig) {
      // 只读一次：原始值同时用于判断 key 是否存在（决定是否安排删除）与解析旧快照记录。
      // 非法形状（非数组）沿用 readLegacyConfigSnapshotRecordsStrict 的 fail-closed 语义。
      const legacySnapshotRaw = await kvGetStrict(kv, kernel.CONFIG_SNAPSHOTS_KEY, {
        type: "json",
      });
      if (
        legacySnapshotRaw !== null &&
        legacySnapshotRaw !== void 0 &&
        !Array.isArray(legacySnapshotRaw)
      ) {
        const error = new Error("Stored legacy config snapshot records are invalid");
        error.code = "CONFIG_SNAPSHOTS_INVALID";
        error.status = 409;
        throw error;
      }
      const legacySnapshotRecords = Array.isArray(legacySnapshotRaw) ? legacySnapshotRaw : [];
      const configMeta = kernel.normalizeRevisionMeta(buildHashedMetaPayload(nextConfig));
      const mutationPlan = [
        {
          type: "put",
          key: kernel.CONFIG_KEY,
          value: JSON.stringify(nextConfig),
        },
        {
          type: "put",
          key: kernel.CONFIG_META_KEY,
          value: JSON.stringify(configMeta),
        },
      ];
      // 旧版配置快照只在 V19 之前的部署里存在。上一次保存已经删掉，此后每次保存都白做 2 次 delete。
      // 用原始值判断存在性（空数组也算存在），避免为判断再读一次 KV。
      if (legacySnapshotRaw !== null && legacySnapshotRaw !== void 0) {
        mutationPlan.unshift(
          { type: "delete", key: kernel.CONFIG_SNAPSHOTS_KEY, value: "" },
          { type: "delete", key: kernel.CONFIG_SNAPSHOTS_META_KEY, value: "" },
        );
      }
      // 遗留 KV 缓存（V19 之前的 sys:cf_dash_cache 系列）已经改用 D1 表，这里只负责清理。
      // 逐个 delete 每次保存都要 3 次往返；list 一次就能确认是否还有残留，清空后只剩 1 次。
      const staleCacheKeys = await kernel
        .listKvKeys(kv, { prefix: LEGACY_CF_DASH_CACHE_KV_KEY_PREFIX })
        .catch(() => null);
      const legacyCacheKeysToDelete =
        staleCacheKeys === null
          ? kernel.buildLegacyConfigCacheKeys(prevConfig, nextConfig)
          : staleCacheKeys
              .map((entry) => String(entry?.name || entry || "").trim())
              .filter(Boolean);
      for (const key of legacyCacheKeysToDelete)
        mutationPlan.push({
          type: "delete",
          key,
          value: "",
        });
      const previouslyReferencedRevisions = kernel.collectReferencedAdminIndexUploadRevisions(
        prevConfig,
        legacySnapshotRecords,
      );
      const retainedRevisions = kernel.collectReferencedAdminIndexUploadRevisions(nextConfig, []);
      for (const revision of previouslyReferencedRevisions) {
        if (retainedRevisions.has(revision)) continue;
        mutationPlan.push({
          type: "delete",
          key: kernel.buildAdminIndexUploadKey(revision),
          value: "",
        });
      }
      return mutationPlan;
    },
    async commitRuntimeConfig(rawConfig, options = {}) {
      const { prevConfig, nextConfig, configuredHost, dnsPlans, ctx, kv, env } =
        await kernel.prepareRuntimeConfigPersistence(rawConfig, options);
      assertExpectedRuntimeConfigRevision(options.expectedConfigRevision, prevConfig);
      if (serializeConfigValue(prevConfig) === serializeConfigValue(nextConfig)) {
        await kernel.ensureConfigMeta(kv, nextConfig, { ctx });
        return nextConfig;
      }
      const appliedDnsPlans = [];
      let activeDnsPlan = null;
      let configMutationStarted = false;
      try {
        for (const plan of dnsPlans) {
          activeDnsPlan = plan;
          await kernel.persistHostPrefixDnsSyncPlan(plan, {
            env,
            kv,
            ctx,
            config: nextConfig,
            requestHost: configuredHost,
          });
          appliedDnsPlans.push(plan);
          activeDnsPlan = null;
        }
        configMutationStarted = true;
        const mutationPlan = await kernel.buildRuntimeConfigMutationPlan(
          kv,
          prevConfig,
          nextConfig,
        );
        await kernel.applyKvMutationsWithRollback(kv, mutationPlan);
        if (env) primeRuntimeConfigCache(env, nextConfig);
        else invalidateRuntimeConfigCache();
        await kernel.invalidateDashboardSnapshotCacheForConfigChange(env, {
          prevConfig,
          nextConfig,
        });
        return nextConfig;
      } catch (error) {
        const rollbackFailures = [];
        const rollbackDnsPlans = activeDnsPlan
          ? [...appliedDnsPlans, activeDnsPlan]
          : appliedDnsPlans;
        for (let index = rollbackDnsPlans.length - 1; index >= 0; index -= 1)
          try {
            await kernel.persistHostPrefixDnsSyncPlan(
              { steps: rollbackDnsPlans[index].rollbackSteps },
              {
                env,
                kv,
                ctx,
                config: nextConfig,
                requestHost: configuredHost,
                skipHistory: true,
              },
            );
          } catch (rollbackError) {
            rollbackFailures.push(getErrorMessage(rollbackError, "dns_rollback_failed"));
          }
        if (error && typeof error === "object") {
          const configRollbackConflicts = Array.isArray(error?.details?.rollbackConflicts)
            ? error.details.rollbackConflicts
            : [];
          const configRollbackFailures = Array.isArray(error?.details?.rollbackFailures)
            ? error.details.rollbackFailures
            : [];
          error.details = {
            ...(isPlainObject(error.details) ? error.details : {}),
            hostPrefixDnsSyncAttempted: dnsPlans.length > 0,
            hostPrefixDnsSyncedCount: appliedDnsPlans.length,
            failedHostPrefixDnsHost: String(
              activeDnsPlan?.nextDnsHost || activeDnsPlan?.previousDnsHost || "",
            ),
            rollbackAttempted: rollbackDnsPlans.length > 0 || configMutationStarted,
            rollbackSucceeded:
              rollbackFailures.length === 0 &&
              configRollbackConflicts.length === 0 &&
              configRollbackFailures.length === 0,
            rollbackError: [...rollbackFailures, ...configRollbackFailures].join("; "),
            rollbackConflicts: configRollbackConflicts,
          };
        }
        throw error;
      }
    },
    async commitSourceDirectNodesConfigWithinMutation(env, kv, ctx, options = {}) {
      if (!kv) return null;
      const currentConfig = env
        ? await getRuntimeConfigStrict(env)
        : sanitizeRuntimeConfig((await kv.get(kernel.CONFIG_KEY, { type: "json" })) || {});
      const currentSelection = normalizeNodeNameList(currentConfig.sourceDirectNodes || []);
      const nextSelection = reconcileNamedNodeSelection(currentSelection, {
        renameMap: options.renameMap,
        removedNames: options.removedNames,
        allowedNames: options.allowedNames,
      });
      if (serializeConfigValue(currentSelection) === serializeConfigValue(nextSelection))
        return currentConfig;
      return kernel.commitRuntimeConfig(
        {
          ...currentConfig,
          sourceDirectNodes: nextSelection,
        },
        {
          env,
          kv,
          ctx,
        },
      );
    },
    async commitSingleNodeMainVideoStreamShortcutShadowWithinMutation(env, kv, ctx, options = {}) {
      if (!kv) return null;
      const currentConfig = env
        ? await getRuntimeConfigStrict(env)
        : sanitizeRuntimeConfig((await kv.get(kernel.CONFIG_KEY, { type: "json" })) || {});
      const originalName = String(options.originalName || "")
        .trim()
        .toLowerCase();
      const nodeName = String(options.nodeName || "")
        .trim()
        .toLowerCase();
      const nextMode = normalizeNodeMainVideoStreamMode(options.mode);
      let nextSelection = normalizeNodeNameList(currentConfig.sourceDirectNodes || []);
      if (originalName && originalName !== nodeName)
        nextSelection = reconcileNamedNodeSelection(nextSelection, {
          renameMap: { [originalName]: nodeName },
        });
      nextSelection = nextSelection.filter(
        (name) =>
          String(name || "")
            .trim()
            .toLowerCase() !== nodeName,
      );
      if (nodeName && nextMode === "direct") nextSelection.push(nodeName);
      nextSelection = normalizeNodeNameList(nextSelection);
      if (
        serializeConfigValue(currentConfig.sourceDirectNodes || []) ===
        serializeConfigValue(nextSelection)
      )
        return currentConfig;
      return kernel.commitRuntimeConfig(
        {
          ...currentConfig,
          sourceDirectNodes: nextSelection,
        },
        {
          env,
          kv,
          ctx,
        },
      );
    },
  };
}
