//#region worker/features/proxy/failover/handler-delivery-methods.js
function defineProxyHandlerDeliveryMethods(dependencies = {}, kernel = {}) {
  return {
    buildErrorResponse(execution, err) {
      const errorMessage = err?.message || String(err || "网关或 CF Workers 内部崩溃");
      const errorCode = String(err?.code || "").toUpperCase();
      let statusCode = 502;
      let statusText = "Bad Gateway";
      let responsePayload = {
        error: "Bad Gateway",
        code: 502,
        message: "All proxy attempts failed.",
      };
      if (errorCode === "UPSTREAM_TIMEOUT" || errorCode === "STREAM_IDLE_TIMEOUT") {
        statusCode = 504;
        statusText = "Gateway Timeout";
        responsePayload = {
          error: "Gateway Timeout",
          code: 504,
          message: "Upstream response timed out.",
        };
      } else if (errorCode === "DIRECT_TRANSPORT_INCOMPATIBLE") {
        statusCode = 409;
        statusText = "Conflict";
        responsePayload = {
          error: "Conflict",
          code: 409,
          message:
            "DIRECT mode is strict and will not fall back to proxy when custom auth headers or cookies are required.",
        };
      } else if (
        errorCode === "CLIENT_ABORTED" ||
        errorCode === "DOWNSTREAM_CANCELLED" ||
        errorCode === "REQUEST_ABORTED"
      ) {
        statusCode = 499;
        statusText = "Client Closed Request";
        responsePayload = {
          error: "Client Closed Request",
          code: 499,
          message: "Client closed request.",
        };
      }
      try {
        execution.requestLifecycle?.abort?.(errorCode ? errorCode.toLowerCase() : "proxy_error");
      } catch {}
      execution.requestLifecycle?.dispose?.();
      const errorLogCategory =
        statusCode === 499
          ? kernel.classifyProxyLogCategory(execution.requestTraits || {})
          : "error";
      // 错误日志同样先判定再构造：默认配置会丢掉图片/海报与元数据的错误行
      if (kernel.shouldRecordAccessLog(execution, { statusCode, category: errorLogCategory })) {
        const redirectDiagnostic = kernel.buildRedirectDiagnosticDetail(
          err?.redirectTrace || execution.redirectTrace,
        );
        const runtimeDiagnostic = kernel.buildRuntimeDiagnosticDetail(execution);
        if (errorCode === "DIRECT_TRANSPORT_INCOMPATIBLE")
          kernel.recordAccessLog(
            execution,
            kernel.buildDirectAccessLogPayload(
              execution,
              statusCode,
              execution.defaultOutboundColo || "",
              { redirectTrace: err?.redirectTrace || execution.redirectTrace },
            ),
          );
        else
          kernel.recordAccessLog(execution, {
            statusCode,
            category: errorLogCategory,
            errorDetail: kernel.appendLogDiagnosticDetail(
              kernel.appendLogDiagnosticDetail(
                errorMessage,
                kernel.buildStreamDiagnosticDetail(execution, null, {
                  flow: "proxy_error",
                  source: "upstream_pending",
                  upstreamHost: err?.lastFinalUrl?.hostname || err?.lastTargetBase?.hostname || "",
                  idleTimeoutMs: kernel.resolveResponseStreamIdleTimeoutMs(
                    execution.requestTraits || {},
                    execution.upstreamTimeoutMs,
                  ),
                }),
              ),
              kernel.appendLogDiagnosticDetail(runtimeDiagnostic, redirectDiagnostic),
            ),
            detailJson: kernel.buildStructuredLogDetail(
              execution,
              { statusCode },
              {
                deliveryMode: "proxy",
                redirectTrace: err?.redirectTrace || execution.redirectTrace,
                redirectMode: "proxy_error",
                redirectUrl: err?.lastFinalUrl,
                decisionReason: errorCode || "proxy_error",
                protocolFailureReason: kernel.classifyProtocolFailureReason(err, {
                  errorCode,
                  message: errorMessage,
                  protocolFallbackRetry: false,
                  upstreamStatus: statusCode,
                }),
                playbackInfoCache: execution.playbackInfoCacheState,
                playbackInfoCacheTtlSec: execution.playbackInfoCacheTtlSec,
                progressRelayMode: execution.progressForwardMode,
                progressIntervalSec: execution.videoProgressForwardIntervalSec,
                upstreamHost: err?.lastFinalUrl?.hostname || err?.lastTargetBase?.hostname || "",
                upstreamStatus: statusCode,
              },
            ),
            outboundColo: execution.defaultOutboundColo || "",
          });
      }
      const errHeaders = new Headers({
        "Content-Type": "application/json; charset=utf-8",
        "Access-Control-Allow-Origin": execution.finalOrigin || "*",
        "Cache-Control": "no-store",
      });
      if (execution.finalOrigin !== "*") mergeVaryHeader(errHeaders, "Origin");
      applySecurityHeaders(errHeaders);
      return new Response(JSON.stringify(responsePayload), {
        status: statusCode,
        statusText,
        headers: errHeaders,
      });
    },
    async handle(request, node, path, name, key, env, ctx, options = {}) {
      if (isEmbyWebProxyPath(path)) {
        const runtimeConfig = isPlainObject(options.runtimeConfig) ? options.runtimeConfig : {};
        const dynamicCors = getCorsHeadersForResponse(
          env,
          request,
          kernel.resolveCorsOrigin(runtimeConfig, request),
        );
        return buildEmbyWebProxyDisabledResponse(request.method, dynamicCors);
      }
      const medbItemsCountsResponse = await serveMedbItemsCounts(request, env, node, name, path);
      if (medbItemsCountsResponse) return medbItemsCountsResponse;
      let execution = await kernel.prepareExecutionContext(
        request,
        node,
        path,
        name,
        key,
        env,
        ctx,
        options,
      );
      if (execution.invalidResponse) return execution.invalidResponse;
      const earlyResponse = await kernel.resolveEarlyResponse(execution);
      if (earlyResponse) return earlyResponse;
      let { targetRecords, invalidResponse } = kernel.parseTargetRecords(
        execution.node,
        execution.finalOrigin,
        { cachedTargetRecords: execution.playbackRouteHotTargetRecords },
      );
      if (invalidResponse) return invalidResponse;
      let failoverTargetRecords = kernel.prepareFailoverOverlay(execution, targetRecords);
      execution.defaultOutboundColo = "";
      let transport = null;
      try {
        transport = await kernel.buildProxyRequestState(
          execution.request,
          execution.node,
          execution.proxyPath,
          execution.requestUrl,
          execution.clientIp,
          execution.requestTraits,
          execution.forceH1,
          failoverTargetRecords,
          {
            effectiveRealClientIpMode: execution.effectiveRealClientIpMode,
            effectiveMediaAuthMode: execution.effectiveMediaAuthMode,
          },
        );
        const playbackInfoCachedResponse = await kernel.tryServePlaybackInfoResponseCache(
          execution,
          transport,
        );
        if (playbackInfoCachedResponse) return playbackInfoCachedResponse;
        const buildFetchOptions = kernel.createBuildFetchOptions(execution, transport);
        const entryDirectResponse = await kernel.maybeBuildEntryDirectResponse(
          execution,
          targetRecords,
          transport,
          buildFetchOptions,
        );
        if (entryDirectResponse) return entryDirectResponse;
        const progressRelayResponse = await kernel.maybeHandlePlaybackProgressRelay(
          execution,
          transport,
          buildFetchOptions,
          transport.retryTargetRecords,
        );
        if (progressRelayResponse) return progressRelayResponse;
        execution.requestLifecycle = createProxyRequestLifecycle(execution.request?.signal);
        const upstreamState = await kernel.executeUpstreamFlow(
          execution,
          transport,
          buildFetchOptions,
        );
        return await kernel.buildSuccessResponse(
          execution,
          buildFetchOptions,
          upstreamState,
          transport,
        );
      } catch (err) {
        return kernel.buildErrorResponse(execution, err);
      }
    },
  };
}
//#endregion
//#region worker/features/proxy/failover/delivery-methods.js
function defineProxyDeliveryMethods(dependencies = {}, kernel = {}) {
  return {
    ...defineProxyCacheDeliveryMethods(dependencies, kernel),
    ...defineProxyUpstreamDeliveryMethods(dependencies, kernel),
    ...defineProxyHandlerDeliveryMethods(dependencies, kernel),
  };
}
