//#region worker/features/proxy/metadata-cache/access-log-methods.js
function defineProxyAccessLogMethods(dependencies = {}, kernel = {}) {
  const { Logger } = dependencies;
  return {
    // 调用方在构造 detailJson/诊断字符串之前先用它短路；未知配置时返回 true，保持原有行为。
    shouldRecordAccessLog(execution = {}, payload = {}, options = {}) {
      const runtimeConfig = isPlainObject(execution.currentConfig)
        ? execution.currentConfig
        : getCachedRuntimeConfig(execution.env);
      if (!isPlainObject(runtimeConfig)) return true;
      return shouldWriteAccessLog(
        runtimeConfig,
        {
          requestMethod: execution.requestMethod,
          requestPath: execution.proxyPath,
          statusCode: payload.statusCode,
          category: payload.category,
        },
        options,
      );
    },
    recordAccessLog(execution, payload = {}) {
      const logData = {
        nodeName: execution.nodeName,
        requestPath: execution.proxyPath,
        requestMethod: execution.requestMethod,
        responseTime: Date.now() - execution.startTime,
        clientIp: execution.clientIp || "unknown",
        inboundColo: execution.logInboundColo || "UNKNOWN",
        outboundColo:
          payload.outboundColo || payload.outboundIp || execution.defaultOutboundColo || "",
        userAgent: execution.request.headers.get("User-Agent"),
        referer: execution.request.headers.get("Referer"),
        runtimeConfig: execution.currentConfig,
        ...payload,
      };
      Logger.record(execution.env, execution.ctx, logData);
    },
    buildOptionsResponse(execution) {
      const headers = new Headers(execution.dynamicCors);
      applySecurityHeaders(headers);
      if (execution.finalOrigin !== "*") mergeVaryHeader(headers, "Origin");
      return new Response(null, { headers });
    },
  };
}
