//#region worker/features/proxy/playback/progress-relay-methods.js
function definePlaybackProgressRelayMethods(dependencies = {}, kernel = {}) {
  return {
    buildPlaybackProgressRelayEntry(intervalMs = 0, waitUntilCtx = null) {
      return {
        lastForwardAt: 0,
        lastTouchedAt: nowMs(),
        intervalMs: Math.max(0, Number(intervalMs) || 0),
        waitUntilCtx: waitUntilCtx || null,
        nodeName: "",
        nodeRevision: "",
        pendingSnapshot: null,
        scheduledFlushAt: 0,
        scheduledPromise: null,
        cancelScheduledDelay: null,
        activeFlushPromise: null,
        terminalState: "",
        terminalAt: 0,
        terminalTombstoneUntil: 0,
      };
    },
    getPlaybackProgressRelayTerminalTtlMs(intervalMs = 0) {
      return Math.max(600 * 1e3, Math.max(1, Number(intervalMs) || 0) * 20);
    },
    isPlaybackProgressRelayTerminal(entry, now = nowMs()) {
      if (
        !entry ||
        String(entry.terminalState || "")
          .trim()
          .toLowerCase() !== "stopped"
      )
        return false;
      return Number(entry.terminalTombstoneUntil || 0) > now;
    },
    markPlaybackProgressRelayStopped(sessionKey, execution) {
      const relayMap = cacheState.PlaybackProgressRelay;
      if (!(relayMap instanceof Map) || !sessionKey) return null;
      const intervalMs = Math.max(0, Number(execution?.videoProgressForwardIntervalSec) || 0) * 1e3;
      const entry =
        relayMap.get(sessionKey) ||
        kernel.buildPlaybackProgressRelayEntry(intervalMs, execution?.ctx || null);
      const stoppedAt = nowMs();
      entry.intervalMs = intervalMs > 0 ? intervalMs : Math.max(0, Number(entry.intervalMs) || 0);
      entry.waitUntilCtx = execution?.ctx || entry.waitUntilCtx || null;
      entry.nodeName = String(execution?.nodeName || entry.nodeName || "")
        .trim()
        .toLowerCase();
      entry.nodeRevision = String(
        execution?.nodeDerivedCacheRevision || entry.nodeRevision || "",
      ).trim();
      try {
        entry.cancelScheduledDelay?.();
      } catch {}
      entry.cancelScheduledDelay = null;
      entry.scheduledPromise = null;
      entry.pendingSnapshot = null;
      entry.scheduledFlushAt = 0;
      entry.terminalState = "stopped";
      entry.terminalAt = stoppedAt;
      entry.terminalTombstoneUntil =
        stoppedAt + kernel.getPlaybackProgressRelayTerminalTtlMs(entry.intervalMs);
      entry.lastTouchedAt = stoppedAt;
      if (!setBoundedPlaybackProgressRelayEntry(sessionKey, entry)) {
        releasePlaybackProgressRelayEntry(entry);
        return null;
      }
      return entry;
    },
    cleanupPlaybackProgressRelay(now = nowMs()) {
      const relayMap = cacheState.PlaybackProgressRelay;
      if (!(relayMap instanceof Map) || relayMap.size <= 0) return;
      const staleWindowMs = Math.max(
        3e4,
        Math.max(1, Number(DEFAULT_VIDEO_PROGRESS_FORWARD_INTERVAL_SEC) || 1) * 2e4,
      );
      for (const [sessionKey, entry] of relayMap) {
        const touchedAt = Number(entry?.lastTouchedAt || entry?.lastForwardAt || 0) || 0;
        const hasPending = !!entry?.pendingSnapshot || !!entry?.activeFlushPromise;
        const terminalTombstoneUntil = Number(entry?.terminalTombstoneUntil || 0) || 0;
        if (terminalTombstoneUntil > 0) {
          if (!hasPending && terminalTombstoneUntil <= now)
            deletePlaybackProgressRelayEntry(sessionKey);
          continue;
        }
        if (!hasPending && touchedAt > 0 && touchedAt + staleWindowMs <= now)
          deletePlaybackProgressRelayEntry(sessionKey);
      }
      const maxEntries = Math.max(1, Number(Config.Defaults.VideoProgressForwardSessionMax) || 1);
      while (relayMap.size > maxEntries) {
        let oldestKey = "";
        for (const [candidateKey, candidate] of relayMap)
          if (!candidate?.activeFlushPromise) {
            oldestKey = candidateKey;
            break;
          }
        if (!oldestKey) break;
        deletePlaybackProgressRelayEntry(oldestKey);
      }
    },
    buildPlaybackProgressSnapshot(execution, transport, buildFetchOptions, targetRecord) {
      if (
        !execution ||
        !transport ||
        typeof buildFetchOptions !== "function" ||
        !isTargetRecord(targetRecord)
      )
        return null;
      if (
        (transport.preparedBodyMode === "buffered"
          ? Number(transport.preparedBody?.byteLength) || 0
          : 0) > DEFAULT_VIDEO_PROGRESS_SNAPSHOT_MAX_BYTES
      )
        return null;
      const preparedBody =
        transport.preparedBodyMode === "buffered" && transport.preparedBody
          ? transport.preparedBody.slice(0)
          : transport.preparedBody;
      return {
        ctx: execution.ctx,
        nodeName: String(execution.nodeName || "")
          .trim()
          .toLowerCase(),
        nodeRevision: String(execution.nodeDerivedCacheRevision || "").trim(),
        targetRecord,
        proxyPath: String(execution.proxyPath || "/"),
        requestUrl: new URL(execution.requestUrl.toString()),
        buildFetchOptions,
        requestMethod: String(execution.request?.method || "POST").toUpperCase(),
        preparedBodyMode: transport.preparedBodyMode,
        preparedBody,
        upstreamTimeoutMs: execution.upstreamTimeoutMs,
      };
    },
    schedulePlaybackProgressRelayFlush(sessionKey, entry) {
      if (
        !entry?.pendingSnapshot ||
        entry?.scheduledFlushAt > 0 ||
        kernel.isPlaybackProgressRelayTerminal(entry)
      )
        return;
      const intervalMs = Math.max(0, Number(entry.intervalMs) || 0);
      if (intervalMs <= 0) return;
      const dueAt = Math.max(nowMs(), Number(entry.lastForwardAt) || 0) + intervalMs;
      entry.scheduledFlushAt = dueAt;
      entry.lastTouchedAt = nowMs();
      const delay = createCancelableDelay(Math.max(0, dueAt - nowMs()));
      const waitPromise = (async () => {
        if (!(await delay.promise)) return;
        const currentEntry = cacheState.PlaybackProgressRelay.get(sessionKey);
        if (
          !currentEntry ||
          currentEntry !== entry ||
          Number(currentEntry.scheduledFlushAt) !== dueAt
        )
          return;
        currentEntry.scheduledFlushAt = 0;
        await kernel.flushPlaybackProgressRelayEntry(sessionKey, {
          background: true,
          attachToCtx: false,
        });
      })().finally(() => {
        if (entry.scheduledPromise !== waitPromise) return;
        entry.scheduledPromise = null;
        entry.cancelScheduledDelay = null;
      });
      entry.scheduledPromise = waitPromise;
      entry.cancelScheduledDelay = delay.cancel;
      const waitUntilCtx = entry.waitUntilCtx || entry.pendingSnapshot?.ctx || null;
      if (waitUntilCtx?.waitUntil) waitUntilCtx.waitUntil(waitPromise);
    },
    async forwardPlaybackProgressSnapshot(snapshot) {
      if (!snapshot) return null;
      const upstream = await kernel.performUpstreamFetch(
        snapshot.targetRecord,
        snapshot.proxyPath,
        snapshot.requestUrl,
        snapshot.buildFetchOptions,
        {
          method: snapshot.requestMethod,
          bodyMode: snapshot.preparedBodyMode,
          body: snapshot.preparedBody,
          timeoutMs: snapshot.upstreamTimeoutMs,
        },
      );
      try {
        try {
          await upstream.response.body?.cancel?.();
        } catch {}
      } finally {
        try {
          upstream.releaseFetchController?.();
        } catch {}
      }
      return upstream.response;
    },
    async flushPlaybackProgressRelayEntry(sessionKey, options = {}) {
      const relayMap = cacheState.PlaybackProgressRelay;
      const entry = relayMap.get(sessionKey);
      if (!entry) return false;
      if (kernel.isPlaybackProgressRelayTerminal(entry)) return false;
      if (entry.activeFlushPromise) {
        if (options.background === true) return false;
        try {
          await entry.activeFlushPromise;
        } catch {}
      }
      if (!entry.pendingSnapshot) return false;
      const snapshot = entry.pendingSnapshot;
      entry.pendingSnapshot = null;
      try {
        entry.cancelScheduledDelay?.();
      } catch {}
      entry.cancelScheduledDelay = null;
      entry.scheduledPromise = null;
      entry.scheduledFlushAt = 0;
      entry.lastForwardAt = nowMs();
      entry.lastTouchedAt = entry.lastForwardAt;
      const flushPromise = (async () => {
        try {
          await kernel.forwardPlaybackProgressSnapshot(snapshot);
          return true;
        } catch {
          const currentEntry = relayMap.get(sessionKey);
          if (currentEntry && currentEntry === entry && !currentEntry.pendingSnapshot) {
            currentEntry.pendingSnapshot = snapshot;
            currentEntry.lastForwardAt = nowMs();
            currentEntry.lastTouchedAt = currentEntry.lastForwardAt;
          }
          return false;
        } finally {
          const currentEntry = relayMap.get(sessionKey);
          if (currentEntry && currentEntry === entry) {
            currentEntry.activeFlushPromise = null;
            currentEntry.lastTouchedAt = nowMs();
            if (currentEntry.pendingSnapshot)
              kernel.schedulePlaybackProgressRelayFlush(sessionKey, currentEntry);
          }
        }
      })();
      entry.activeFlushPromise = flushPromise;
      if (options.attachToCtx === true && entry.waitUntilCtx?.waitUntil)
        entry.waitUntilCtx.waitUntil(flushPromise);
      return (await flushPromise) === true;
    },
    async flushPlaybackProgressBeforeStopped(execution) {
      const sessionKey = String(execution?.progressForwardSessionKey || "").trim();
      if (!sessionKey) return false;
      const entry = cacheState.PlaybackProgressRelay.get(sessionKey);
      if (!entry) return false;
      if (entry.activeFlushPromise)
        try {
          await entry.activeFlushPromise;
        } catch {}
      if (!entry.pendingSnapshot) return false;
      try {
        entry.cancelScheduledDelay?.();
      } catch {}
      entry.cancelScheduledDelay = null;
      entry.scheduledPromise = null;
      entry.scheduledFlushAt = 0;
      return await kernel.flushPlaybackProgressRelayEntry(sessionKey, {
        background: false,
        attachToCtx: false,
      });
    },
    buildPlaybackProgressThrottleResponse(execution) {
      const responseHeaders = kernel.buildEdgeResponseHeaders(execution.finalOrigin);
      const throttleLogCategory = kernel.classifyProxyLogCategory(execution.requestTraits);
      if (
        kernel.shouldRecordAccessLog(execution, {
          statusCode: 204,
          category: throttleLogCategory,
        })
      )
        kernel.recordAccessLog(execution, {
          statusCode: 204,
          category: throttleLogCategory,
          errorDetail: kernel.buildProgressRelayDiagnosticDetail(execution),
          detailJson: kernel.buildStructuredLogDetail(
            execution,
            { statusCode: 204 },
            {
              deliveryMode: "proxy",
              redirectMode: "progress_relay",
              decisionReason: execution.progressForwardMode || "progress_relay_throttled",
              progressRelayMode: execution.progressForwardMode,
              progressIntervalSec: execution.videoProgressForwardIntervalSec,
              upstreamStatus: 204,
            },
          ),
          outboundColo: execution.defaultOutboundColo || "",
        });
      return new Response(null, {
        status: 204,
        statusText: "No Content",
        headers: responseHeaders,
      });
    },
    async maybeHandlePlaybackProgressRelay(
      execution,
      transport,
      buildFetchOptions,
      targetRecords = [],
    ) {
      if (execution?.requestTraits?.isPlaybackSessionControlRequest !== true) return null;
      const intervalSec = Math.max(0, Number(execution?.videoProgressForwardIntervalSec) || 0);
      if (
        execution?.videoProgressForwardEnabled !== true ||
        intervalSec <= 0 ||
        !execution?.ctx?.waitUntil
      ) {
        execution.progressForwardMode = "pass_through";
        return null;
      }
      const sessionInfo = kernel.resolvePlaybackProgressSessionKey(execution, transport);
      execution.progressForwardSessionKey = String(sessionInfo.sessionKey || "").trim();
      if (sessionInfo.parseError) {
        execution.progressForwardMode = "parse_bypass";
        return null;
      }
      if (execution.requestTraits.isPlaybackStartedRequest === true) {
        execution.progressForwardMode = "started_passthrough";
        if (execution.progressForwardSessionKey)
          deletePlaybackProgressRelayEntry(execution.progressForwardSessionKey);
        return null;
      }
      if (execution.requestTraits.isPlaybackStoppedRequest === true) {
        execution.progressForwardMode = (await kernel.flushPlaybackProgressBeforeStopped(execution))
          ? "flush_before_stopped"
          : "stopped_passthrough";
        if (execution.progressForwardSessionKey)
          kernel.markPlaybackProgressRelayStopped(execution.progressForwardSessionKey, execution);
        return null;
      }
      if (execution.requestTraits.isPlaybackProgressRequest !== true) return null;
      const targetRecord = isTargetRecord(targetRecords[0]) ? targetRecords[0] : null;
      if (!targetRecord) {
        execution.progressForwardMode = "pass_through";
        return null;
      }
      if (
        execution.requestMethod !== "GET" &&
        execution.requestMethod !== "HEAD" &&
        transport?.preparedBodyMode !== "buffered"
      ) {
        execution.progressForwardMode = "unbuffered_bypass";
        return null;
      }
      const relayMap = cacheState.PlaybackProgressRelay;
      kernel.cleanupPlaybackProgressRelay();
      const sessionKey =
        execution.progressForwardSessionKey ||
        `fallback:${execution.clientIp}:${execution.proxyPath}`;
      let relayEntry = relayMap.get(sessionKey);
      if (!relayEntry)
        relayEntry = kernel.buildPlaybackProgressRelayEntry(intervalSec * 1e3, execution.ctx);
      relayEntry.intervalMs = intervalSec * 1e3;
      relayEntry.waitUntilCtx = execution.ctx;
      relayEntry.nodeName = String(execution.nodeName || "")
        .trim()
        .toLowerCase();
      relayEntry.nodeRevision = String(execution.nodeDerivedCacheRevision || "").trim();
      const now = nowMs();
      relayEntry.lastTouchedAt = now;
      if (kernel.isPlaybackProgressRelayTerminal(relayEntry, now)) {
        execution.progressForwardMode = "late_progress_dropped_after_stopped";
        return kernel.buildPlaybackProgressThrottleResponse(execution);
      }
      relayEntry.terminalState = "";
      relayEntry.terminalAt = 0;
      relayEntry.terminalTombstoneUntil = 0;
      if (!setBoundedPlaybackProgressRelayEntry(sessionKey, relayEntry)) {
        releasePlaybackProgressRelayEntry(relayEntry);
        execution.progressForwardMode = "capacity_bypass";
        return null;
      }
      if (
        !(relayEntry.lastForwardAt > 0 && now - relayEntry.lastForwardAt < relayEntry.intervalMs) &&
        !relayEntry.activeFlushPromise &&
        !relayEntry.pendingSnapshot
      ) {
        relayEntry.pendingSnapshot = null;
        relayEntry.scheduledFlushAt = 0;
        relayEntry.lastForwardAt = now;
        execution.progressForwardMode = "forward_now";
        return null;
      }
      const snapshot = kernel.buildPlaybackProgressSnapshot(
        execution,
        transport,
        buildFetchOptions,
        targetRecord,
      );
      if (!snapshot) {
        execution.progressForwardMode = "snapshot_bypass";
        return null;
      }
      relayEntry.pendingSnapshot = snapshot;
      relayEntry.lastTouchedAt = now;
      execution.progressForwardMode = "throttled_204";
      kernel.schedulePlaybackProgressRelayFlush(sessionKey, relayEntry);
      return kernel.buildPlaybackProgressThrottleResponse(execution);
    },
  };
}
