            return {
              ok: false,
              targetRecord,
              targetKey,
              reason: "probe_winner_aborted",
              elapsedMs,
              aborted: true,
            };
          return {
            ok: false,
            targetRecord,
            targetKey,
            reason: errorCode === "UPSTREAM_TIMEOUT" ? "probe_timeout" : "probe_network_error",
            elapsedMs,
            aborted: isAbortLikeError(error),
          };
