      telemetry.probeElapsedMs = Math.max(0, Number(probeResult?.elapsedMs) || 0);
      telemetry.probeWinner = String(probeResult?.winnerTargetKey || "").trim();
      if (
        !probeResult ||
        probeResult.status !== "ok" ||
        !isTargetRecord(probeResult.winnerTargetRecord)
      ) {
        telemetry.overlay = "probe_miss";
        telemetry.fastFailReason =
          String(probeResult?.reason || "probe_no_winner").trim() || "probe_no_winner";
        return null;
      }
