      const retentionDays = clampIntegerConfig(
        config.logRetentionDays,
        Config.Defaults.LogRetentionDays,
        1,
        Config.Defaults.LogRetentionDaysMax,
      );
      const startTs = Math.max(0, now.getTime() - retentionDays * 24 * 60 * 60 * 1e3);
      const endTs = now.getTime();
      await kernel.rebuildStatsHourlyWindow(db, {
        startTs,
        endTs,
        utcOffsetMinutes,
      });
