//#region worker/features/storage/d1/analytics-dashboard-methods.js
function defineAnalyticsDashboardMethods(dependencies = {}, kernel = {}) {
  return {
    buildCloudflareKvQuotaCard({
      planProfile = {},
      planState = {},
      usageState = {},
      namespaceId = "",
      nowTimestamp = nowMs(),
    } = {}) {
      const profile = getCloudflareQuotaLimitProfile(planProfile?.planClass);
      /** @type {CloudflareKvUsagePayload} */
      const usagePayload = isPlainObject(usageState?.payload) ? usageState.payload : {};
      const namespaceTitle = String(
        usagePayload.namespaceTitle ||
          planProfile?.resourceMeta?.kv?.namespaceTitle ||
          namespaceId ||
          "未命名 Namespace",
      ).trim();
      const metrics = [
        buildCloudflareQuotaMetricRow({
          key: "read",
          label: "读",
          used: usagePayload.readCount,
          limit: profile.kv.read,
          kind: "count",
        }),
        buildCloudflareQuotaMetricRow({
          key: "write",
          label: "写",
          used: usagePayload.writeCount,
          limit: profile.kv.write,
          kind: "count",
        }),
        buildCloudflareQuotaMetricRow({
          key: "storage",
          label: "容量",
          used: usagePayload.storageBytes,
          limit: profile.kv.storageBytes,
          kind: "bytes",
        }),
      ];
      const staleScopes = [];
      if (planState?.stale === true) staleScopes.push("计划信息");
      if (usageState?.stale === true) staleScopes.push("实时指标");
      const detailParts = [];
      if (staleScopes.length > 0) detailParts.push(`${staleScopes.join("、")} 使用 stale cache`);
      detailParts.push(
        `delete：${formatCount(usagePayload.deleteCount)} / ${formatCount(profile.kv.delete)}`,
      );
      detailParts.push(
        `list：${formatCount(usagePayload.listCount)} / ${formatCount(profile.kv.list)}`,
      );
      detailParts.push(`命名空间：${namespaceTitle}`);
      const cacheAgeText = formatCloudflareCacheAgeText(usageState?.cachedAt, nowTimestamp);
      if (cacheAgeText) detailParts.push(cacheAgeText);
      detailParts.push(
        profile.planClass === "paid"
          ? "容量条按 1 GB included quota 展示，PAID 下这是 included quota，不是硬停止线"
          : "容量条按 1 GB included quota 展示",
      );
      const exceededLabels = collectCloudflareQuotaExceededMetricLabels(metrics);
      if (exceededLabels.length > 0)
        detailParts.push(`超额项目：${exceededLabels.join("、")}（进度条按 100% 封顶）`);
      if (usageState?.error)
        detailParts.push(`Cloudflare 详情：${trimCloudflareRuntimeErrorMessage(usageState.error)}`);
      return buildCloudflareRuntimeQuotaCardPayload({
        title: "KV",
        status: staleScopes.length > 0 ? "partial_failure" : "success",
        summary: `${profile.planLabel} 计划 · ${profile.periodLabel}配额`,
        detail: detailParts.join("；"),
        planLabel: profile.planLabel,
        periodLabel: profile.periodLabel,
        resourceLabel: namespaceTitle,
        metrics,
      });
    },
    buildCloudflareD1QuotaCard({
      planProfile = {},
      planState = {},
      usageState = {},
      databaseId = "",
      nowTimestamp = nowMs(),
    } = {}) {
      const profile = getCloudflareQuotaLimitProfile(planProfile?.planClass);
      /** @type {CloudflareD1UsagePayload} */
      const usagePayload = isPlainObject(usageState?.payload) ? usageState.payload : {};
      const databaseName = String(
        usagePayload.databaseName ||
          planProfile?.resourceMeta?.d1?.databaseName ||
          databaseId ||
          "未命名数据库",
      ).trim();
      const metrics = [
        buildCloudflareQuotaMetricRow({
          key: "rowsRead",
          label: "读",
          used: usagePayload.rowsRead,
          limit: profile.d1.rowsRead,
          kind: "count",
        }),
        buildCloudflareQuotaMetricRow({
          key: "rowsWritten",
          label: "写",
          used: usagePayload.rowsWritten,
          limit: profile.d1.rowsWritten,
          kind: "count",
        }),
        buildCloudflareQuotaMetricRow({
          key: "storage",
          label: "容量",
          used: usagePayload.fileSizeBytes,
          limit: profile.d1.storageBytes,
          kind: "bytes",
        }),
      ];
      const staleScopes = [];
      if (planState?.stale === true) staleScopes.push("计划信息");
      if (usageState?.stale === true) staleScopes.push("实时指标");
      const detailParts = [];
      if (staleScopes.length > 0) detailParts.push(`${staleScopes.join("、")} 使用 stale cache`);
      detailParts.push(
        `SQL 次数：读 ${formatCount(usagePayload.readQueries)} / 写 ${formatCount(usagePayload.writeQueries)}`,
      );
      detailParts.push(`数据库：${databaseName}`);
      const cacheAgeText = formatCloudflareCacheAgeText(usageState?.cachedAt, nowTimestamp);
      if (cacheAgeText) detailParts.push(cacheAgeText);
      detailParts.push(`容量条按单库硬上限 ${formatBytes(profile.d1.storageBytes)} 展示`);
      const exceededLabels = collectCloudflareQuotaExceededMetricLabels(metrics);
      if (exceededLabels.length > 0)
        detailParts.push(`超额项目：${exceededLabels.join("、")}（进度条按 100% 封顶）`);
      if (usageState?.error)
        detailParts.push(`Cloudflare 详情：${trimCloudflareRuntimeErrorMessage(usageState.error)}`);
      return buildCloudflareRuntimeQuotaCardPayload({
        title: "D1",
        status: staleScopes.length > 0 ? "partial_failure" : "success",
        summary: `${profile.planLabel} 计划 · ${profile.periodLabel}配额`,
        detail: detailParts.join("；"),
        planLabel: profile.planLabel,
        periodLabel: profile.periodLabel,
        resourceLabel: databaseName,
        metrics,
      });
    },
    async buildDashboardD1WriteHotspotPayload(env, options = {}) {
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const nowTimestamp = Math.max(0, Number(options?.nowMs) || nowMs());
      const utcOffsetMinutes = normalizeScheduleUtcOffsetMinutes(config.scheduleUtcOffsetMinutes);
      const accountId = String(config.cfAccountId || "").trim();
      const apiToken = String(config.cfApiToken || "").trim();
      const databaseId = String(config.cfD1DatabaseId || "").trim();
      const basePlaceholder = {
        utcOffsetMinutes,
        nowMs: nowTimestamp,
        source: "cloudflare_d1_analytics",
      };
      if (!accountId || !apiToken || !databaseId)
        return buildDashboardD1WriteHotspotPlaceholder({
          ...basePlaceholder,
          status: "unconfigured",
          summary: "D1 写入热点尚未启用",
          detail: "请先在账号设置中填写 Cloudflare 账号 ID、API 令牌与 D1 Database ID。",
        });
      const startTs =
        buildOffsetDayWindow(new Date(nowTimestamp), utcOffsetMinutes).startTs - 8640 * 60 * 1e3;
      const buckets = await fetchCloudflareD1WriteHotspotMetrics({
        accountId,
        apiToken,
        databaseId,
        startIso: new Date(startTs).toISOString(),
        endIso: new Date(nowTimestamp).toISOString(),
        utcOffsetMinutes,
      });
      const bucketMap = new Map(buckets.map((item) => [`${item.dateKey}:${item.hour}`, item]));
      const hourLabels = buildDashboardD1WriteHotspotHourLabels();
      const dayRows = [];
      let totalRowsWritten = 0;
      let totalWriteQueries = 0;
      let maxRowsWritten = 0;
      let peakBucket = null;
      for (const bucket of buckets) {
        totalRowsWritten += Math.max(0, Number(bucket?.rowsWritten) || 0);
        totalWriteQueries += Math.max(0, Number(bucket?.writeQueries) || 0);
        if ((Number(bucket?.rowsWritten) || 0) > maxRowsWritten) {
          maxRowsWritten = Math.max(0, Number(bucket?.rowsWritten) || 0);
          peakBucket = bucket;
        }
      }
      for (let dayIndex = 0; dayIndex < 7; dayIndex += 1) {
        const dateKey = buildOffsetClockParts(
          startTs + dayIndex * 24 * 60 * 60 * 1e3,
          utcOffsetMinutes,
        ).dateKey;
        dayRows.push({
          key: dateKey,
          dateKey,
          label: formatDashboardD1WriteHotspotDayLabel(dateKey),
          cells: Array.from({ length: 24 }, (_, hour) => {
            const bucket = bucketMap.get(`${dateKey}:${hour}`) || null;
            const rowsWritten = Math.max(0, Number(bucket?.rowsWritten) || 0);
            const writeQueries = Math.max(0, Number(bucket?.writeQueries) || 0);
            const intensity = maxRowsWritten > 0 ? rowsWritten / maxRowsWritten : 0;
            return buildDashboardD1WriteHotspotCell(
              dateKey,
              hour,
              rowsWritten,
              writeQueries,
              intensity,
            );
          }),
        });
      }
      const peakLabel = peakBucket
        ? `峰值：${formatDashboardD1WriteHotspotDayLabel(peakBucket.dateKey)} ${String(peakBucket.hour).padStart(2, "0")}:00 写入 ${formatCount(peakBucket.rowsWritten)} 行 / SQL ${formatCount(peakBucket.writeQueries)} 次`
        : "";
      return {
        title: "D1 写入热点图",
        status: "success",
        source: "cloudflare_d1_analytics",
        summary:
          totalRowsWritten > 0
            ? `最近 7 天累计写入 ${formatCount(totalRowsWritten)} 行`
            : `最近 7 天未检测到 D1 写入`,
        detail:
          totalRowsWritten > 0
            ? "热点强度按 rowsWritten 计算；悬停单元格可查看对应小时的 SQL 写次数。"
            : "Cloudflare D1 Analytics 当前窗口内没有返回 rowsWritten 数据。",
        periodLabel: `最近 7 天 · ${formatUtcOffsetMinutesLabel(utcOffsetMinutes)}`,
        hourLabels,
        rows: dayRows,
        available: totalRowsWritten > 0,
        totalRowsWritten,
        totalWriteQueries,
        peakLabel,
        legendMaxLabel: formatCount(maxRowsWritten),
      };
    },
    async buildDashboardMonthlyTrafficPayload(env, options = {}) {
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const nowTimestamp = Math.max(0, Number(options.nowMs) || nowMs());
      const monthWindow =
        options?.monthWindow ||
        buildOffsetMonthWindow(new Date(nowTimestamp), config.scheduleUtcOffsetMinutes);
      const cfZoneId = String(config.cfZoneId || "").trim();
      const cfApiToken = String(config.cfApiToken || "").trim();
      const basePayload = {
        period: "month",
        periodKey: monthWindow.monthKey,
        periodLabel: monthWindow.periodLabel,
        generatedAt: new Date(nowTimestamp).toISOString(),
        cacheStatus: "live",
      };
      if (!cfZoneId || !cfApiToken)
        return normalizeDashboardMonthlyTrafficPayload({
          ...basePayload,
          traffic: "未配置",
          cfAnalyticsLoaded: false,
          cfAnalyticsStatus: "未配置 Cloudflare",
          cfAnalyticsError: "请在账号设置中填写并保存 Cloudflare Zone ID 与 API 令牌",
          trafficSourceText: "本月视频流量：未配置 Cloudflare，无法获取 CF Zone 总流量",
        });
      const dayMs = 1440 * 60 * 1e3;
      const utcOffsetMinutes = normalizeScheduleUtcOffsetMinutes(config.scheduleUtcOffsetMinutes);
      const kv = options?.kv || kernel.getKV(env);
      const retentionCutoffTs = nowTimestamp - CF_ZONE_ANALYTICS_RETENTION_DAYS * dayMs;
      const dayWindows = [];
      for (let startTs = monthWindow.startTs; startTs <= monthWindow.endTs; startTs += dayMs)
        dayWindows.push({
          startTs,
          endTs: Math.min(monthWindow.endTs, startTs + dayMs - 1),
          dateKey: buildOffsetClockParts(new Date(startTs), utcOffsetMinutes).dateKey,
        });
      let totalBytes = 0;
      let archivedDayCount = 0;
      let missingDayCount = 0;
      let cfSuccessDayCount = 0;
      let firstCfError = null;
      const maxConcurrentQueries = 4;
      for (let index = 0; index < dayWindows.length; index += maxConcurrentQueries) {
        const dayParts = await Promise.all(
          dayWindows
            .slice(index, index + maxConcurrentQueries)
            .map(async ({ startTs, endTs, dateKey }) => {
              const archivedBytes = await readCfDailyTrafficArchiveBytes(kv, cfZoneId, dateKey);
              let cfBytes = null;
              try {
                cfBytes = await fetchCfZoneEdgeResponseBytes(cfZoneId, cfApiToken, startTs, endTs);
              } catch (error) {
                firstCfError = firstCfError || error;
              }
              if (cfBytes === null)
                return archivedBytes !== null
                  ? {
                      bytes: archivedBytes,
                      source: "archive",
                    }
                  : {
                      bytes: 0,
                      source: "missing",
                    };
              if (endTs < nowTimestamp && startTs >= retentionCutoffTs && archivedBytes === null)
                await writeCfDailyTrafficArchiveBytes(kv, cfZoneId, {
                  dateKey,
                  bytes: cfBytes,
                  dayEndTs: endTs,
                });
              if (cfBytes === 0 && archivedBytes !== null)
                return {
                  bytes: archivedBytes,
                  source: "archive",
                };
              if (cfBytes === 0 && startTs < retentionCutoffTs)
                return {
                  bytes: 0,
                  source: "missing",
                };
              return {
                bytes: cfBytes,
                source: "cf",
              };
            }),
        );
        for (const dayPart of dayParts) {
          totalBytes += Math.max(0, Number(dayPart?.bytes) || 0);
          if (dayPart?.source === "archive") archivedDayCount += 1;
          else if (dayPart?.source === "missing") missingDayCount += 1;
          else if (dayPart?.source === "cf") cfSuccessDayCount += 1;
        }
      }
      if (cfSuccessDayCount === 0 && archivedDayCount === 0 && firstCfError) throw firstCfError;
      const partialNotice =
        missingDayCount > 0
          ? `本地归档缺失 ${missingDayCount} 天（免费版 CF Zone 分析仅保留约 ${CF_ZONE_ANALYTICS_RETENTION_DAYS} 天）`
          : "";
      return normalizeDashboardMonthlyTrafficPayload({
        ...basePayload,
        traffic: formatBytes(totalBytes),
        totalBytes,
        cfAnalyticsLoaded: true,
        cfAnalyticsStatus:
          missingDayCount > 0 ? "Cloudflare 统计正常（部分日期缺失）" : "Cloudflare 统计正常",
        cfAnalyticsError: "",
        cfAnalyticsDetail: partialNotice,
        trafficSourceText: `${monthWindow.periodLabel}视频流量：CF Zone 总流量（edgeResponseBytes）${archivedDayCount > 0 ? `（本地归档 ${archivedDayCount} 天）` : ""}${partialNotice ? `；${partialNotice}` : ""}`,
        warning: partialNotice,
      });
    },
    async snapshotCfDailyTrafficArchive(env, options = {}) {
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const kv = options?.kv || kernel.getKV(env);
      const cfZoneId = String(config.cfZoneId || "").trim();
      const cfApiToken = String(config.cfApiToken || "").trim();
      if (!kv || !cfZoneId || !cfApiToken)
        return {
          status: "skipped",
          storedCount: 0,
          errors: [],
        };
      const nowTimestamp = Math.max(0, Number(options?.nowMs) || nowMs());
      const utcOffsetMinutes = normalizeScheduleUtcOffsetMinutes(config.scheduleUtcOffsetMinutes);
      const todayWindow = buildOffsetDayWindow(new Date(nowTimestamp), utcOffsetMinutes);
      const dayMs = 1440 * 60 * 1e3;
      const retentionCutoffTs = nowTimestamp - CF_ZONE_ANALYTICS_RETENTION_DAYS * dayMs;
      let storedCount = 0;
      const errors = [];
      for (let offsetDays = 1; offsetDays <= CF_DAILY_TRAFFIC_SNAPSHOT_DAYS; offsetDays += 1) {
        const startTs = todayWindow.startTs - offsetDays * dayMs;
        const endTs = startTs + dayMs - 1;
        const dateKey = buildOffsetClockParts(new Date(startTs), utcOffsetMinutes).dateKey;
        if (startTs < retentionCutoffTs) continue;
        if ((await readCfDailyTrafficArchiveBytes(kv, cfZoneId, dateKey)) !== null) continue;
        try {
          const bytes = await fetchCfZoneEdgeResponseBytes(cfZoneId, cfApiToken, startTs, endTs);
          if (
            await writeCfDailyTrafficArchiveBytes(kv, cfZoneId, {
              dateKey,
              bytes,
              dayEndTs: endTs,
            })
          )
            storedCount += 1;
        } catch (error) {
          errors.push(String(error?.message || error));
        }
      }
      return {
        status: errors.length > 0 ? "partial_failure" : "success",
        storedCount,
        errors,
      };
    },
    async getDashboardMonthlyTrafficPayload(env, options = {}) {
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const ctx = options?.ctx || null;
      const forceRefresh = options?.forceRefresh === true;
      const nowTimestamp = Math.max(0, Number(options.nowMs) || nowMs());
      const monthWindow =
        options?.monthWindow ||
        buildOffsetMonthWindow(new Date(nowTimestamp), config.scheduleUtcOffsetMinutes);
      const zoneId = String(config.cfZoneId || "").trim();
      if (!zoneId || !String(config.cfApiToken || "").trim())
        return await kernel.buildDashboardMonthlyTrafficPayload(env, {
          config,
          monthWindow,
          nowMs: nowTimestamp,
        });
      const cacheKey = makeDashboardMonthlyTrafficCacheKey(
        zoneId,
        monthWindow.monthKey,
        config.scheduleUtcOffsetMinutes,
      );
      const cacheRequest = makeDashboardMonthlyTrafficCacheRequest(cacheKey);
      const edgeCache = getDefaultCacheHandle();
      let staleEntry = null;
      const memoryEntry = cacheState.DashboardMonthlyTrafficCache.get(cacheKey);
      if (memoryEntry?.staleUntil > nowTimestamp) {
        setBoundedMapEntry(cacheState.DashboardMonthlyTrafficCache, cacheKey, memoryEntry, 64);
        staleEntry = memoryEntry;
        if (!forceRefresh && memoryEntry.expiresAt > nowTimestamp)
          return normalizeDashboardMonthlyTrafficPayload({
            ...memoryEntry.payload,
            cacheStatus: "cache",
          });
      } else if (memoryEntry) cacheState.DashboardMonthlyTrafficCache.delete(cacheKey);
      if (edgeCache && cacheRequest)
        try {
          const cachedResponse = await edgeCache.match(cacheRequest);
          if (cachedResponse) {
            const cachedBody = await readResponseTextWithLimit(
              cachedResponse,
              REMOTE_ERROR_RESPONSE_MAX_BYTES,
            );
            const cachedEnvelope = cachedBody.exceeded
              ? null
              : JSON.parse(cachedBody.text || "null");
            if (
              Number(cachedEnvelope?.version) === 1 &&
              String(cachedEnvelope?.cacheKey || "") === cacheKey &&
              Number(cachedEnvelope?.staleUntil) > nowTimestamp
            ) {
              staleEntry = {
                payload: normalizeDashboardMonthlyTrafficPayload(cachedEnvelope.payload),
                cachedAt: Number(cachedEnvelope.cachedAt) || 0,
                expiresAt: Number(cachedEnvelope.expiresAt) || 0,
                staleUntil: Number(cachedEnvelope.staleUntil) || 0,
              };
              setBoundedMapEntry(cacheState.DashboardMonthlyTrafficCache, cacheKey, staleEntry, 64);
              if (!forceRefresh && staleEntry.expiresAt > nowTimestamp)
                return normalizeDashboardMonthlyTrafficPayload({
                  ...staleEntry.payload,
                  cacheStatus: "cache",
                });
            }
          }
        } catch (error) {
          logRuntimeFailure("dashboard.monthly_traffic_cache_read_failed", error, { cacheKey });
        }
      try {
        return await runSingleFlight(
          buildSingleFlightKey([
            "dashboard_monthly_traffic",
            cacheKey,
            forceRefresh ? "force" : "default",
          ]),
          async () => {
            const payload = await kernel.buildDashboardMonthlyTrafficPayload(env, {
              config,
              monthWindow,
              nowMs: nowTimestamp,
            });
            const cachedAt = nowTimestamp;
            const expiresAt = cachedAt + DASHBOARD_MONTHLY_TRAFFIC_CACHE_TTL_MS;
            const staleUntil = cachedAt + DASHBOARD_MONTHLY_TRAFFIC_STALE_TTL_MS;
            const envelope = {
              version: 1,
              cacheKey,
              cachedAt,
              expiresAt,
              staleUntil,
              payload,
            };
            setBoundedMapEntry(
              cacheState.DashboardMonthlyTrafficCache,
              cacheKey,
              {
                payload,
                cachedAt,
                expiresAt,
                staleUntil,
              },
              64,
            );
            if (edgeCache && cacheRequest) {
              const cacheWriteTask = edgeCache.put(
                cacheRequest,
                new Response(JSON.stringify(envelope), {
                  headers: {
                    "Content-Type": "application/json; charset=utf-8",
                    "Cache-Control": `public, max-age=${Math.floor(DASHBOARD_MONTHLY_TRAFFIC_STALE_TTL_MS / 1e3)}`,
                  },
                }),
              );
              if (ctx)
                ctx.waitUntil(
                  withNonCriticalFallback(
                    cacheWriteTask,
                    "dashboard.monthly_traffic_cache_write",
                    { cacheKey },
                    null,
                  ),
                );
              else
                await withNonCriticalFallback(
                  cacheWriteTask,
                  "dashboard.monthly_traffic_cache_write",
                  { cacheKey },
                  null,
                );
            }
            return payload;
          },
        );
      } catch (error) {
        if (staleEntry?.payload && staleEntry.staleUntil > nowTimestamp)
          return normalizeDashboardMonthlyTrafficPayload({
            ...staleEntry.payload,
            cacheStatus: "stale",
            warning: trimDashboardSnapshotErrorMessage(error, "monthly_traffic_refresh_failed"),
          });
        const cfDiag = classifyCloudflareAnalyticsError(error?.message || error, { zoneId });
        return normalizeDashboardMonthlyTrafficPayload({
          periodKey: monthWindow.monthKey,
          periodLabel: monthWindow.periodLabel,
          traffic: "CF 查询失败",
          cfAnalyticsLoaded: false,
          cfAnalyticsStatus: cfDiag.status,
          cfAnalyticsError: cfDiag.hint,
          cfAnalyticsDetail: cfDiag.detail,
          trafficSourceText: `${monthWindow.periodLabel}视频流量：CF Zone 总流量（edgeResponseBytes）`,
          generatedAt: new Date(nowTimestamp).toISOString(),
          cacheStatus: "live",
        });
      }
    },
  };
}
//#endregion
//#region worker/features/storage/d1/analytics-runtime-methods.js
function defineAnalyticsRuntimeMethods(dependencies = {}, kernel = {}) {
  const { CacheManager, withAdminShellRuntimeStatus } = dependencies;
  return {
    async buildDashboardStatsPayload(env, options = {}) {
      const ctx = options?.ctx || null;
      const kv = options?.kv || kernel.getKV(env);
      const db = options?.db || kernel.getDB(env);
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const nowTimestamp = Math.max(0, Number(options.nowMs) || nowMs());
      const dayWindow =
        options?.dayWindow ||
        buildOffsetDayWindow(new Date(nowTimestamp), config.scheduleUtcOffsetMinutes);
      const skipD1WriteHotspot = options?.skipD1WriteHotspot !== false;
      const d1WriteHotspotPromise = skipD1WriteHotspot
        ? null
        : kernel.buildDashboardD1WriteHotspotPayload(env, {
            config,
            nowMs: nowTimestamp,
          });
      let todayRequests = null;
      let todayTraffic = "未配置";
      let nodeCount = 0;
      let cfAnalyticsLoaded = false;
      let requestsLoaded = false;
      let cfAnalyticsStatus = "";
      let cfAnalyticsError = "";
      let cfAnalyticsDetail = "";
      let requestSource = "pending";
      let requestSourceText = "等待数据加载";
      let trafficSourceText = "视频流量口径：CF Zone 总流量";
      let generatedAt = new Date(nowTimestamp).toISOString();
      let hourlySeries = Array.from({ length: 24 }, (_, hour) => ({
        label: String(hour).padStart(2, "0") + ":00",
        total: 0,
      }));
      let playCount = 0;
      let infoCount = 0;
      let zoneName = "";
      let d1WriteHotspot = buildDashboardD1WriteHotspotPlaceholder({
        utcOffsetMinutes: config.scheduleUtcOffsetMinutes,
        nowMs: nowTimestamp,
      });
      nodeCount = (await CacheManager.getNodesListStrict(env, ctx)).length || 0;
      const dateString = dayWindow.dateKey;
      const startOfDayTs = dayWindow.startTs;
      const endOfDayTs = dayWindow.endTs;
      const cfZoneId = String(config.cfZoneId || "").trim();
      const cfApiToken = String(config.cfApiToken || "").trim();
      if (cfZoneId && cfApiToken) {
        const startIso = new Date(startOfDayTs).toISOString();
        const endIso = new Date(endOfDayTs).toISOString();
        const query = `
                query {
                  viewer {
                    zones(filter: { zoneTag: ${toGraphQLString(cfZoneId)} }) {
                      series: httpRequestsAdaptiveGroups(limit: 10000, filter: { datetime_geq: ${toGraphQLString(startIso)}, datetime_leq: ${toGraphQLString(endIso)} }) {
                        count
                        dimensions { datetimeHour }
                        sum { edgeResponseBytes }
                      }
                    }
                  }
                }`;
        try {
          const zone = await fetchCloudflareZoneDetailsSoft(cfZoneId, cfApiToken, {
            scope: "dashboard.stats.zone_lookup",
            context: { feature: "dashboard_stats" },
          });
          zoneName = String(zone?.name || "").trim();
          const zoneData = await fetchCloudflareGraphQLZone(cfZoneId, cfApiToken, query);
          if (zoneData) {
            let zoneTotalReq = 0;
            let totalBytes = 0;
            let zoneHourlySeries = Array.from({ length: 24 }, (_, hour) => ({
              label: String(hour).padStart(2, "0") + ":00",
              total: 0,
            }));
            (Array.isArray(zoneData.series)
              ? [...zoneData.series].sort((a, b) =>
                  String(a?.dimensions?.datetimeHour || "").localeCompare(
                    String(b?.dimensions?.datetimeHour || ""),
                  ),
                )
              : []
            ).forEach((item) => {
              const requestCount = Number(item.count) || 0;
              const byteCount = Number(item.sum?.edgeResponseBytes) || 0;
              zoneTotalReq += requestCount;
              totalBytes += byteCount;
              const rawHour = item?.dimensions?.datetimeHour;
              if (rawHour && !Number.isNaN(new Date(rawHour).getTime())) {
                const hour = buildOffsetClockParts(
                  new Date(rawHour),
                  config.scheduleUtcOffsetMinutes,
                ).hour;
                zoneHourlySeries[hour].total += requestCount;
              }
            });
            todayTraffic = formatBytes(totalBytes);
            cfAnalyticsLoaded = true;
            cfAnalyticsStatus = "Cloudflare 统计正常";
            trafficSourceText = "视频流量当前对齐：CF Zone 总流量（edgeResponseBytes）";
            try {
              const workerUsage = await fetchCloudflareWorkerUsageMetrics({
                cfAccountId: String(config.cfAccountId || "").trim(),
                cfZoneId,
                cfApiToken,
                startIso,
                endIso,
                utcOffsetMinutes: config.scheduleUtcOffsetMinutes,
              });
              if (workerUsage && Number.isFinite(workerUsage.totalRequests)) {
                todayRequests = workerUsage.totalRequests;
                hourlySeries = workerUsage.hourlySeries;
                requestsLoaded = true;
                requestSource = "workers_usage";
                requestSourceText = "今日请求量口径：Cloudflare Workers Usage";
                cfAnalyticsStatus = "Cloudflare 统计正常";
              }
            } catch (error) {
              console.log("CF workers usage fetch failed", error);
            }
            if (!requestsLoaded) {
              todayRequests = zoneTotalReq;
              hourlySeries = zoneHourlySeries;
              requestsLoaded = true;
              requestSource = "zone_analytics";
              requestSourceText = "今日请求量当前对齐：Cloudflare Zone Analytics";
            }
          } else {
            cfAnalyticsStatus = "Zone 未命中";
            cfAnalyticsError = "GraphQL 返回空；请检查 Zone ID 或权限";
            todayTraffic = "CF 无统计数据";
          }
        } catch (error) {
          const cfDiag = classifyCloudflareAnalyticsError(error?.message || error, {
            zoneId: cfZoneId,
          });
          cfAnalyticsStatus = cfDiag.status;
          cfAnalyticsError = cfDiag.hint;
          cfAnalyticsDetail = cfDiag.detail;
          todayTraffic = "CF 查询失败";
        }
      } else {
        cfAnalyticsStatus = "未配置 Cloudflare";
        cfAnalyticsError = "请在账号设置中填写并保存 Cloudflare Zone ID 与 API 令牌";
        trafficSourceText = "视频流量当前对齐：未配置 Cloudflare，无法获取 CF Zone 总流量";
      }
      if (db)
        try {
          await kernel.ensureStatsHourlyWindowAligned(
            {
              db,
              kv,
            },
            {
              config,
              now: dayWindow.now,
            },
          );
          const logReadiness = await kernel.resolveLogsReadiness({
            db,
            kv,
          });
          const aggregatedRows =
            logReadiness.statsReady === true
              ? await kernel.getDailyStatsHourly(db, dateString)
              : [];
          playCount = aggregatedRows.reduce(
            (sum, row) => sum + (Number(row?.play_count || row?.playCount) || 0),
            0,
          );
          infoCount = aggregatedRows.reduce(
            (sum, row) => sum + (Number(row?.playback_info_count || row?.playbackInfoCount) || 0),
            0,
          );
          if (!requestsLoaded && logReadiness.statsReady === true) {
            todayRequests = aggregatedRows.reduce(
              (sum, row) => sum + (Number(row?.request_count || row?.requestCount) || 0),
              0,
            );
            hourlySeries = Array.from({ length: 24 }, (_, hour) => ({
              label: String(hour).padStart(2, "0") + ":00",
              total: 0,
            }));
            for (const row of aggregatedRows) {
              const index = Number.parseInt(String(row?.bucket_hour ?? row?.bucketHour), 10);
              if (!Number.isNaN(index) && hourlySeries[index])
                hourlySeries[index].total += Number(row?.request_count || row?.requestCount) || 0;
            }
            requestsLoaded = true;
            requestSource = "d1_hourly_stats";
            requestSourceText = "今日请求量当前对齐：本地 D1 预聚合";
          }
        } catch (error) {
          console.log("DB aggregated stats read failed:", error);
        }
      if (!requestsLoaded) {
        todayRequests = null;
        if (!cfZoneId || !cfApiToken) {
          requestSource = "unconfigured";
          requestSourceText = db
            ? "今日请求量暂不可用：未配置 Cloudflare 联动，且本地 D1 日志未初始化或不可读"
            : "今日请求量未配置：未绑定 D1，且未配置 Cloudflare 联动";
        } else {
          requestSource = "pending";
          requestSourceText = db
            ? "今日请求量暂不可用：Cloudflare 请求数查询失败，且本地 D1 日志未初始化或不可读"
            : "今日请求量暂不可用：Cloudflare 请求数查询失败，且未绑定 D1";
        }
      }
      if (!skipD1WriteHotspot)
        try {
          d1WriteHotspot = await d1WriteHotspotPromise;
        } catch (error) {
          console.log("D1 write hotspot read failed:", error);
          d1WriteHotspot = buildDashboardD1WriteHotspotPlaceholder({
            utcOffsetMinutes: config.scheduleUtcOffsetMinutes,
            nowMs: nowTimestamp,
            status: "failed",
            source: "cloudflare_d1_analytics",
            summary: "D1 写入热点暂不可用",
            detail: trimCloudflareRuntimeErrorMessage(error, "d1_write_hotspot_failed"),
          });
        }
      const requestCountDisplay =
        todayRequests === null || todayRequests === void 0
          ? requestSource === "unconfigured"
            ? "未配置"
            : "暂不可用"
          : String(Number(todayRequests) || 0);
      return sanitizeDashboardStatsPayload({
        todayRequests,
        requestCountDisplay,
        todayTraffic,
        hourlySeries,
        requestSource,
        requestSourceText,
        trafficSourceText,
        generatedAt,
        zoneName,
        cfAnalyticsLoaded,
        cfAnalyticsStatus,
        cfAnalyticsError,
        cfAnalyticsDetail,
        playCount,
        infoCount,
        nodeCount,
        cacheStatus: "live",
        d1WriteHotspot,
      });
    },
    async buildDashboardRuntimeStatusPayload(env, options = {}) {
      const db = options?.db || kernel.getDB(env);
      const kv = options?.kv || kernel.getKV(env);
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const forceRefresh = options?.forceRefresh === true;
      const opsStatus = await kernel.getOpsStatus({
        kv,
        db,
      });
      let cloudflare = {
        kv: buildCloudflareRuntimeQuotaSkippedCard(
          "KV",
          "Cloudflare 配额尚未加载",
          "等待运行状态接口返回 Cloudflare 配额数据。",
        ),
        d1: buildCloudflareRuntimeQuotaSkippedCard(
          "D1",
          "Cloudflare 配额尚未加载",
          "等待运行状态接口返回 Cloudflare 配额数据。",
        ),
      };
      try {
        cloudflare = await kernel.getCloudflareRuntimeQuotaStatus(env, {
          config,
          db,
          forceRefresh,
        });
      } catch (error) {
        const detail = trimCloudflareRuntimeErrorMessage(error, "runtime_config_read_failed");
        cloudflare = {
          kv: buildCloudflareRuntimeQuotaFailedCard("KV", "Cloudflare 配额读取失败", detail),
          d1: buildCloudflareRuntimeQuotaFailedCard("D1", "Cloudflare 配额读取失败", detail),
        };
      }
      return {
        ...(opsStatus && typeof opsStatus === "object" ? opsStatus : {}),
        cloudflare,
      };
    },
    async getRuntimeStatusPayload(env, options = {}) {
      const db = options?.db || kernel.getDB(env);
      const kv = options?.kv || kernel.getKV(env);
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const initHealth = buildInitHealth(env);
      const forceRefresh = options?.forceRefresh === true;
      const generatedAtMs = Math.max(0, Number(options.nowMs) || nowMs());
      const runtimeStatus = await runSingleFlight(
        buildSingleFlightKey(["runtime_status", forceRefresh ? "force" : "default"]),
        async () =>
          kernel.buildDashboardRuntimeStatusPayload(env, {
            kv,
            db,
            config,
            forceRefresh,
          }),
      );
      return {
        status: withAdminShellRuntimeStatus(runtimeStatus, env, config, initHealth),
        cacheMeta: buildDashboardSnapshotCacheMeta({
          cacheStatus: "live",
          cachedAt: generatedAtMs,
          expiresAt: generatedAtMs,
          updatedAt: generatedAtMs,
          generatedAt: new Date(generatedAtMs).toISOString(),
          warning: "",
          partial: false,
        }),
      };
    },
    async getDashboardSnapshotPayload(env, options = {}) {
      const db = options?.db || kernel.getDB(env);
      const kv = options?.kv || kernel.getKV(env);
      const ctx = options?.ctx || null;
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const forceRefresh = options?.forceRefresh === true;
      const nowTimestamp = Math.max(0, Number(options.nowMs) || nowMs());
      const dayWindow =
        options?.dayWindow ||
        buildOffsetDayWindow(new Date(nowTimestamp), config.scheduleUtcOffsetMinutes);
      const zoneId = String(config.cfZoneId || "").trim();
      const cacheKey = makeCfDashCacheDbKey(zoneId, dayWindow.dateKey);
      const cachedEntry = db
        ? await kernel.getCfDashboardCacheEntry(db, cacheKey, {
            nowMs: nowTimestamp,
            includeExpired: true,
          })
        : null;
      if (!forceRefresh && db) {
        const freshEntry = cachedEntry && cachedEntry.expiresAt > nowTimestamp ? cachedEntry : null;
        if (freshEntry && freshEntry.version === 8)
          return withDashboardSnapshotCacheStatus(freshEntry.payload, "cache", {
            cachedAt: freshEntry.cachedAt,
            expiresAt: freshEntry.expiresAt,
            updatedAt: freshEntry.updatedAt,
            generatedAt:
              freshEntry.payload?.cacheMeta?.generatedAt ||
              freshEntry.payload?.stats?.generatedAt ||
              new Date(freshEntry.cachedAt || nowTimestamp).toISOString(),
            warning: "",
          });
      }
      const staleEntry = cachedEntry;
      try {
        const snapshot = await runSingleFlight(
          buildSingleFlightKey([
            "dashboard_snapshot",
            cacheKey,
            forceRefresh ? "force" : "default",
          ]),
          async () => {
            const [stats, runtimeStatus] = await Promise.all([
              kernel.buildDashboardStatsPayload(env, {
                ctx,
                kv,
                db,
                config,
                dayWindow,
                nowMs: nowTimestamp,
              }),
              kernel.buildDashboardRuntimeStatusPayload(env, {
                kv,
                db,
                config,
                forceRefresh,
              }),
            ]);
            const liveSnapshot = withDashboardSnapshotCacheStatus(
              {
                stats,
                runtimeStatus,
                cacheMeta: { generatedAt: stats.generatedAt },
              },
              "live",
              {
                cachedAt: nowTimestamp,
                expiresAt: nowTimestamp + 3600 * 1e3,
                updatedAt: nowTimestamp,
                generatedAt: stats.generatedAt,
                warning: "",
              },
            );
            if (db) {
              const cacheWriteTask = kernel.putCfDashboardCacheEntry(db, {
                cacheKey,
                zoneId: zoneId || "default",
                bucketDate: dayWindow.dateKey,
                payload: liveSnapshot,
                version: 8,
                cachedAt: nowTimestamp,
                expiresAt: nowTimestamp + 3600 * 1e3,
                updatedAt: nowTimestamp,
              });
              if (ctx)
                ctx.waitUntil(
                  withNonCriticalFallback(
                    cacheWriteTask,
                    "dashboard.cache_write",
                    { cacheKey },
                    null,
                  ),
                );
              else
                await withNonCriticalFallback(
                  cacheWriteTask,
                  "dashboard.cache_write",
                  { cacheKey },
                  null,
                );
            }
            return liveSnapshot;
          },
        );
        return withDashboardSnapshotCacheStatus(snapshot, "live", {
          cachedAt: nowTimestamp,
          expiresAt: nowTimestamp + 3600 * 1e3,
          updatedAt: nowTimestamp,
          generatedAt: snapshot?.stats?.generatedAt || "",
        });
      } catch (error) {
        if (staleEntry && staleEntry.version === 8)
          return withDashboardSnapshotCacheStatus(staleEntry.payload, "stale", {
            cachedAt: staleEntry.cachedAt,
            expiresAt: staleEntry.expiresAt,
            updatedAt: staleEntry.updatedAt,
            generatedAt:
              staleEntry.payload?.cacheMeta?.generatedAt ||
              staleEntry.payload?.stats?.generatedAt ||
              new Date(staleEntry.cachedAt || nowTimestamp).toISOString(),
            warning: trimDashboardSnapshotErrorMessage(error),
            partial: true,
          });
        throw error;
      }
    },
    async getDashboardCachedSnapshotPayload(env, options = {}) {
      const db = options?.db || kernel.getDB(env);
      if (!db) return null;
      const config = sanitizeRuntimeConfig(options?.config || (await getRuntimeConfigStrict(env)));
      const nowTimestamp = Math.max(0, Number(options.nowMs) || nowMs());
      const dayWindow = buildOffsetDayWindow(
        new Date(nowTimestamp),
        config.scheduleUtcOffsetMinutes,
      );
      const cacheKey = makeCfDashCacheDbKey(
        String(config.cfZoneId || "").trim(),
        dayWindow.dateKey,
      );
      const cachedEntry = await kernel.getCfDashboardCacheEntry(db, cacheKey, {
        nowMs: nowTimestamp,
        includeExpired: true,
      });
      if (!cachedEntry || cachedEntry.version !== 8) return null;
      return withDashboardSnapshotCacheStatus(
        cachedEntry.payload,
        cachedEntry.expiresAt > nowTimestamp ? "cache" : "stale",
        {
          cachedAt: cachedEntry.cachedAt,
          expiresAt: cachedEntry.expiresAt,
          updatedAt: cachedEntry.updatedAt,
          generatedAt:
            cachedEntry.payload?.cacheMeta?.generatedAt ||
            cachedEntry.payload?.stats?.generatedAt ||
            "",
          warning: cachedEntry.expiresAt > nowTimestamp ? "" : "dashboard_cache_expired",
          partial: cachedEntry.expiresAt <= nowTimestamp,
        },
      );
    },
    async getCloudflareRuntimeQuotaStatus(env, options = {}) {
      const db = options?.db || kernel.getDB(env);
      const runtimeConfig = sanitizeRuntimeConfig(options?.config || {});
      const forceRefresh = options?.forceRefresh === true;
      const accountId = String(runtimeConfig.cfAccountId || "").trim();
      const apiToken = String(runtimeConfig.cfApiToken || "").trim();
      const namespaceId = String(runtimeConfig.cfKvNamespaceId || "").trim();
      const databaseId = String(runtimeConfig.cfD1DatabaseId || "").trim();
      if (!accountId || !apiToken)
        return {
          kv: buildCloudflareRuntimeQuotaSkippedCard(
            "KV",
            "未配置 Cloudflare 账号联动",
            "请先在账号设置中填写 Cloudflare 账号 ID 与 API 令牌。",
          ),
          d1: buildCloudflareRuntimeQuotaSkippedCard(
            "D1",
            "未配置 Cloudflare 账号联动",
            "请先在账号设置中填写 Cloudflare 账号 ID 与 API 令牌。",
          ),
        };
      const nowTimestamp = nowMs();
      const planCacheMinutes = clampIntegerConfig(
        runtimeConfig.cfQuotaPlanCacheMinutes,
        Config.Defaults.CfQuotaPlanCacheMinutes,
        1,
        1440,
      );
      const usageCacheTtlMs = planCacheMinutes * 60 * 1e3;
      let planState;
      try {
        planState = await kernel.loadCfRuntimeCachePayload(db, {
          cacheKey: `plan_profile:${accountId}:${namespaceId || "-"}:${databaseId || "-"}`,
          cacheGroup: "plan_profile",
          resourceId: accountId,
          ttlMs: planCacheMinutes * 60 * 1e3,
          nowMs: nowTimestamp,
          skipCacheRead: forceRefresh,
          loader: async () => {
            const resolvedProfile = resolveCloudflareQuotaPlanProfileFromUsageModel(
              await fetchCloudflareAccountUsageModel(accountId, apiToken),
            );
            const [namespaceDetails, databaseDetails] = await Promise.all([
              namespaceId
                ? withNonCriticalFallback(
                    fetchCloudflareKvNamespaceDetails(accountId, namespaceId, apiToken),
                    "cf_runtime.plan_profile.kv_details",
                    {
                      accountId,
                      namespaceId,
                    },
                    null,
                  )
                : null,
              databaseId
                ? withNonCriticalFallback(
                    fetchCloudflareD1DatabaseDetails(accountId, databaseId, apiToken),
                    "cf_runtime.plan_profile.d1_details",
                    {
                      accountId,
                      databaseId,
                    },
                    null,
                  )
                : null,
            ]);
            return {
              planClass: resolvedProfile.planClass,
              planLabel: resolvedProfile.planLabel,
              periodLabel: resolvedProfile.periodLabel,
              usageModel: resolvedProfile.usageModel,
              resourceMeta: {
                kv: { namespaceTitle: String(namespaceDetails?.title || "").trim() },
                d1: { databaseName: String(databaseDetails?.name || "").trim() },
              },
            };
          },
        });
      } catch (error) {
        const detail = trimCloudflareRuntimeErrorMessage(error);
        return {
          kv: buildCloudflareRuntimeQuotaFailedCard("KV", "Cloudflare 计划信息读取失败", detail),
          d1: buildCloudflareRuntimeQuotaFailedCard("D1", "Cloudflare 计划信息读取失败", detail),
        };
      }
      const rawPlanPayload = isPlainObject(planState?.payload) ? planState.payload : {};
      const resolvedPlanProfile = {
        ...resolveCloudflareQuotaPlanProfile({
          usageModel: rawPlanPayload.usageModel || rawPlanPayload.planClass,
          override: runtimeConfig.cfQuotaPlanOverride,
        }),
        resourceMeta: {
          kv: {
            namespaceTitle: String(rawPlanPayload?.resourceMeta?.kv?.namespaceTitle || "").trim(),
          },
          d1: { databaseName: String(rawPlanPayload?.resourceMeta?.d1?.databaseName || "").trim() },
        },
      };
      const periodContext = getCloudflareQuotaPeriodContext(resolvedPlanProfile.planClass);
      const [kvCard, d1Card] = await Promise.all([
        (async () => {
          if (!namespaceId)
            return buildCloudflareRuntimeQuotaSkippedCard(
              "KV",
              "未配置 KV Namespace",
              "请在账号设置中填写 Cloudflare KV Namespace ID。",
            );
          try {
            const usageState = await kernel.loadCfRuntimeCachePayload(db, {
              cacheKey: `usage_metrics:kv:${accountId}:${namespaceId}:${periodContext.cacheBucketKey}`,
              cacheGroup: "usage_metrics",
              resourceId: `kv:${namespaceId}`,
              ttlMs: usageCacheTtlMs,
              nowMs: nowTimestamp,
              skipCacheRead: forceRefresh,
              loader: async () => {
                return {
                  ...(await fetchCloudflareKvQuotaMetrics({
                    accountId,
                    apiToken,
                    namespaceId,
                    startIso: periodContext.startIso,
                    endIso: periodContext.endIso,
                  })),
                  namespaceTitle: String(
                    resolvedPlanProfile?.resourceMeta?.kv?.namespaceTitle || namespaceId,
                  ).trim(),
                };
              },
            });
            return kernel.buildCloudflareKvQuotaCard({
              planProfile: resolvedPlanProfile,
              planState,
              usageState,
              namespaceId,
              nowTimestamp,
            });
          } catch (error) {
            return buildCloudflareRuntimeQuotaFailedCard(
              "KV",
              "KV 指标读取失败",
              trimCloudflareRuntimeErrorMessage(error),
            );
          }
        })(),
        (async () => {
          if (!databaseId)
            return buildCloudflareRuntimeQuotaSkippedCard(
              "D1",
              "未配置 D1 数据库",
              "请在账号设置中填写 Cloudflare D1 Database ID。",
            );
          try {
            const usageState = await kernel.loadCfRuntimeCachePayload(db, {
              cacheKey: `usage_metrics:d1:${accountId}:${databaseId}:${periodContext.cacheBucketKey}`,
              cacheGroup: "usage_metrics",
              resourceId: `d1:${databaseId}`,
              ttlMs: usageCacheTtlMs,
              nowMs: nowTimestamp,
              skipCacheRead: forceRefresh,
              loader: async () => {
                const [metrics, databaseDetails] = await Promise.all([
                  fetchCloudflareD1QuotaMetrics({
                    accountId,
                    apiToken,
                    databaseId,
                    startIso: periodContext.startIso,
                    endIso: periodContext.endIso,
                  }),
                  fetchCloudflareD1DatabaseDetails(accountId, databaseId, apiToken),
                ]);
                return {
                  ...metrics,
                  databaseName: String(
                    databaseDetails?.name ||
                      resolvedPlanProfile?.resourceMeta?.d1?.databaseName ||
                      databaseId,
                  ).trim(),
                  fileSizeBytes: Math.max(
                    0,
                    Number(databaseDetails?.file_size ?? databaseDetails?.fileSize) || 0,
                  ),
                };
              },
            });
            return kernel.buildCloudflareD1QuotaCard({
              planProfile: resolvedPlanProfile,
              planState,
              usageState,
              databaseId,
              nowTimestamp,
            });
          } catch (error) {
            return buildCloudflareRuntimeQuotaFailedCard(
              "D1",
              "D1 指标读取失败",
              trimCloudflareRuntimeErrorMessage(error),
            );
          }
        })(),
      ]);
      return {
        kv: kvCard,
        d1: d1Card,
      };
    },
  };
}
