        String(trigger?.name || "") === kernel.LOGS_FTS_INSERT_TRIGGER &&
        String(trigger?.tbl_name || "") === kernel.LOGS_TABLE &&
        new RegExp(`\\bafter\\s+insert\\s+on\\s+${kernel.LOGS_TABLE}\\b`).test(triggerSql) &&
        new RegExp(`\\binsert\\s+into\\s+${kernel.LOGS_FTS_TABLE}\\s*\\(`).test(triggerSql) &&
        triggerWritesExpectedColumns;
