//#region worker/features/storage/kv/cache-manager.js

function buildCacheServices(dependencies = {}) {
  const { nodeRepository } = dependencies;
  return {
    async getNodesList(env, ctx) {
      const kv = nodeRepository.getKV(env);
      if (!kv) return [];
      const state = getNodeBindingCacheState(kv);
      if (state.NodesListCache && state.NodesListCache.exp > nowMs())
        return state.NodesListCache.data;
      const summaryNodes = await nodeRepository.getNodesSummaryIndex(kv, { ctx });
      if (Array.isArray(summaryNodes)) return summaryNodes;
      const rebuilt = await nodeRepository.rebuildNodeIndexesFromKv(kv, { ctx });
      return Array.isArray(rebuilt?.summaries) ? rebuilt.summaries : [];
    },
    async getNodesListStrict(env, ctx) {
      const kv = nodeRepository.getKV(env);
      if (!kv) return [];
      const state = getNodeBindingCacheState(kv);
      if (state.NodesListCache && state.NodesListCache.exp > nowMs())
        return state.NodesListCache.data;
      const summaryNodes = await nodeRepository.getNodesSummaryIndexStrict(kv, { ctx });
      if (Array.isArray(summaryNodes)) return summaryNodes;
      const rebuilt = await nodeRepository.rebuildNodeIndexesFromKvStrict(kv, { ctx });
      return Array.isArray(rebuilt?.summaries) ? rebuilt.summaries : [];
    },
    async invalidateList(ctx, env = null) {
      const kv = nodeRepository.getKV(env);
      const state = getNodeBindingCacheState(kv);
      state.NodesListCache = null;
      state.NodesIndexCache = null;
      invalidateNodesRevisionCache(kv);
    },
    maybeCleanup(env = null) {
      const nodeState = env
        ? getNodeBindingCacheState(nodeRepository.getKV(env))
        : nodeBindingCacheStates.current();
      const now = nowMs();
      const state = nodeState.CleanupState;
      if (now - (state.lastRunAt || 0) < Config.Defaults.CleanupMinIntervalMs) return;
      state.lastRunAt = now;
      const budget = Config.Defaults.CleanupBudgetMs;
      const chunkSize = Config.Defaults.CleanupChunkSize;
      const iterators =
        state.iterators ||
        (state.iterators = {
          node: null,
          playbackRoute: null,
          crypto: null,
          rate: null,
          log: null,
          playbackInfo: null,
          failover: null,
          progress: null,
          monthlyTraffic: null,
        });
      const start = now;
      const cleanMap = (
        map,
        shouldDelete,
        iteratorKey,
        iteratorStore = iterators,
        deleteEntry = (key) => map.delete(key),
      ) => {
        let iterator = iteratorStore[iteratorKey];
        if (!iterator) {
          iterator = map.entries();
          iteratorStore[iteratorKey] = iterator;
        }
        let scanned = 0;
        while (scanned < chunkSize && (scanned === 0 || nowMs() - start < budget)) {
          const next = iterator.next();
          if (next.done) {
            iteratorStore[iteratorKey] = null;
            break;
          }
          scanned += 1;
          const [k, v] = next.value;
          if (!map.has(k)) continue;
          if (shouldDelete(v, now)) deleteEntry(k);
        }
      };
      if (state.phase === 0) {
        cleanMap(
          nodeState.NodeCache,
          (v) => v?.exp && v.exp < now,
          "node",
          nodeState.CleanupIterators,
        );
        state.phase = 1;
      } else if (state.phase === 1) {
        cleanMap(
          nodeState.PlaybackRouteHotCache,
          (v) => !v || Number(v.expiresAt) <= now,
          "playbackRoute",
          nodeState.CleanupIterators,
        );
        state.phase = 2;
      } else if (state.phase === 2) {
        cleanMap(cacheState.CryptoKeyCache, (v) => v?.exp && v.exp < now, "crypto");
        state.phase = 3;
      } else if (state.phase === 3) {
        cleanMap(runtimeState.RateLimitCache, (v) => !v || v.resetAt < now, "rate");
        state.phase = 4;
      } else if (state.phase === 4) {
        state.phase = 5;
      } else if (state.phase === 5) {
        cleanMap(
          cacheState.PlaybackInfoResponseCache,
          (v) =>
            !v ||
            (Number(v.expiresAt) || 0) <= now ||
            !validatePlaybackInfoCacheEntry(v, DEFAULT_PLAYBACK_INFO_CACHE_ENTRY_MAX_BYTES),
          "playbackInfo",
          iterators,
        );
        state.phase = 6;
      } else if (state.phase === 6) {
        cleanMap(
          cacheState.ProxyFailoverStateCache,
          (v) => {
            if (!v || typeof v !== "object") return true;
            if (v.failingTargets instanceof Map) {
              for (const [targetKey, expiresAt] of v.failingTargets)
                if (Number(expiresAt) <= now) v.failingTargets.delete(targetKey);
            }
            const hasPreferred = Number(v.preferredTargetExpiresAt) > now;
            const hasFailing = v.failingTargets instanceof Map && v.failingTargets.size > 0;
            const hasProbe = !!v.inFlightProbe && Number(v.inFlightProbe.expiresAt) > now;
            const lastProbeAt = Number(v.lastProbeResult?.completedAt) || 0;
            const hasLastProbe =
              !!v.lastProbeResult && lastProbeAt + Config.Defaults.HedgePreferredTtlSec * 1e3 > now;
            return !hasPreferred && !hasFailing && !hasProbe && !hasLastProbe;
          },
          "failover",
        );
        state.phase = 7;
      } else if (state.phase === 7) {
        const staleWindowMs = Math.max(
          3e4,
          Math.max(1, Number(Config.Defaults.VideoProgressForwardIntervalSec) || 1) * 2e4,
        );
        cleanMap(
          cacheState.PlaybackProgressRelay,
          (v) => {
            if (!v || v.pendingSnapshot || v.activeFlushPromise) return !v;
            const terminalUntil = Number(v.terminalTombstoneUntil) || 0;
            if (terminalUntil > 0) return terminalUntil < now;
            const touchedAt = Number(v.lastTouchedAt || v.lastForwardAt) || 0;
            return touchedAt > 0 && touchedAt + staleWindowMs <= now;
          },
          "progress",
          iterators,
          deletePlaybackProgressRelayEntry,
        );
        state.phase = 8;
      } else {
        cleanMap(
          cacheState.DashboardMonthlyTrafficCache,
          (v) => !v || (Number(v.staleUntil) || 0) <= now,
          "monthlyTraffic",
        );
        state.phase = 0;
      }
    },
  };
}
